import math
TIER={'S':('M',2),'M':('p',3),'p':('Y',4)}
def off(n): return n//2 if n%2==0 else (n-1)//2
def center(p): r,c,n=p; return (r+(n-1)/2.0, c+(n-1)/2.0)
def box(p): r,c,n=p; return (r,r+n-1,c,c+n-1)
def overlap(a,b): ar,ar2,ac,ac2=a; br,br2,bc,bc2=b; return not(ar2<br or br2<ar or ac2<bc or bc2<ac)
def gap(a,b):
    ar,ar2,ac,ac2=a; br,br2,bc,bc2=b
    dr=max(br-ar2, ar-br2, 0); dc=max(bc-ac2, ac-bc2, 0)
    return math.hypot(dr,dc)
def inball(p):
    r,c,n=p
    cols={11:(30,34),12:(29,35),13:(28,36),14:(28,36),15:(28,36),16:(28,36),17:(28,36),18:(29,35),19:(30,34)}
    for rr in range(r,r+n):
        lo,hi=cols.get(rr,(99,-99))
        if c<lo or c+n-1>hi: return False
    return True
def sim_click(pieces, inv, click):
    R,C=click
    inr=[p for p in pieces if math.hypot(R-center(p)[0],C-center(p)[1])<=8.05]
    np2=list(pieces); merged=None
    if inr:
        cols={}
        for p in inr: cols.setdefault(p[0],[]).append(p)
        best=None
        for col,ps in cols.items():
            if len(ps)>=2 and col in TIER: best=(col,ps)
        if best:
            col,ps=best; nc,nn=TIER[col]
            keep=[p for p in pieces if p not in ps]
