    R, C = len(g), len(g[0])
    r0 = max(0, r0)
    c0 = max(0, c0)
    r1 = min(R - 1, r1)
    c1 = min(C - 1, c1)
    vals = set()
    for r in range(r0, r1 + 1):
        row = g[r]
        for c in range(c0, c1 + 1):
            vals.add(row[c])
    return len(vals) == 1


def _target_pair(g):
    pair = []
    for r in range(len(g)):
        for c in range(len(g[r])):
            if g[r][c] == "p":
