    if not g:
        return False
    R, C = len(g), len(g[0])
    if r0 < 0 or c0 < 0 or r1 >= R or c1 >= C:
        return False
    for r in range(r0, r1 + 1):
        for c in range(c0, c1 + 1):
            if g[r][c] != ch:
                return False
    return True


